template.css:
html, body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica, sans-serif;
  color: #000;
}

.label {
  box-sizing: border-box;
  width: 58mm;
  height: 30mm;
  padding: 1.4mm 1.6mm 1.2mm;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
}

.top {
  display: flex;
  align-items: flex-start;
  gap: 1.6mm;
  min-height: 0;
}

img.product {
  flex: 0 0 auto;
  width: 11mm;
  height: 11mm;
  object-fit: cover;
  border: 0.2mm solid #111;
}

img.product[src=""] {
  display: none;
}

.info {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4mm;
}

.name {
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.15;
  max-height: 2.3em;
  overflow: hidden;
  word-break: break-word;
}

.price-row {
  display: flex;
  align-items: baseline;
  gap: 1mm;
  margin-top: 0.3mm;
}

.price {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1;
}

.currency {
  font-size: 9px;
  font-weight: 700;
}

.meta {
  font-size: 7.5px;
  line-height: 1.1;
  opacity: 0.9;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.brand {
  flex: 0 0 auto;
  max-width: 10mm;
}

.brand img {
  display: block;
  max-width: 10mm;
  max-height: 6mm;
  width: auto;
  height: auto;
}

.bottom {
  display: flex;
  align-items: flex-end;
  gap: 1.4mm;
  margin-top: 0.8mm;
}

img.barcode {
  height: 8.5mm;
  width: auto;
  max-width: 38mm;
  object-fit: contain;
  object-position: left bottom;
}

.code {
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  line-height: 1;
  padding-bottom: 0.4mm;
  white-space: nowrap;
}
